  LanguageConfig_BPRuleTxt2_CN = {
    Text = "\n\n<Title:[Special Curriculum]>\nThis Special Curriculum runs from {s1} to {s2} (GMT+8). Complete tasks to earn 2× Topic EXP and accelerate your progress."
  },
  LanguageConfig_BPRuleTxt_CN = {
    Text = "<Title:[Topic Categories]>\nFor each issue, Basic Topics are unlocked by default. Keepers can also unlock Advanced Topics to earn a wider variety of rewards.\nStandard issues last for 28 days. Occasionally, Mythag opens Special Topics with shorter durations; during these events, Topic EXP is doubled to help Keepers complete the Topic faster!\n<Blue:Standard Topics (28 Days):>\nUnlocking \"Advanced Topics\" requires Silver Prime ×680 (you immediately receive Silver ×680).\nUnlocking \"Premium Topics\" requires Silver Prime ×1280 (you immediately receive Silver ×1460).\nUpgrading from \"Advanced\" to \"Premium\" requires Silver Prime ×780 (you immediately receive Silver ×780).\n<Blue:Special Topics:>\nTopic EXP gained during the period is doubled.\nUnlocking \"Advanced Topics\" requires Silver Prime ×680 (you immediately receive Silver ×680).\nUnlocking \"Premium Topics\" requires Silver Prime ×980 (you immediately receive Silver ×1070).\nUpgrading from \"Advanced\" to \"Premium\" requires Silver Prime ×390 (you immediately receive Silver ×390).\n<Title:[Premium Topic Privileges]>\nUnlocking \"Premium Topics\" grants specific privileges for the duration of the current issue:\nDuring this Curriculum Season, Basic Active Ions Rewards (Reality Verges, Pure Cores, Silvers, EXP) are tripled. (If you completed Daily Drills before purchasing Premium, the 3× bonus rewards are granted retroactively).\nYou can use \"Time Reversal\" in battles to return to previous turns.\nYou temporarily unlock all cards in \"Traphase.\"\n<Title:[Topic Levels]>\nKeepers gain Topic EXP by completing Topic Tasks to increase their Topic Level and claim rewards.\nDaily Drills refresh at 09:00, and Weekly Trials refresh every Monday at 09:00 (GMT+8).\nAfter reaching Level 50, you will receive an extra reward for every subsequent Level increase."
  },
