  LanguageConfig_LotteryPhoneticDialogue10_CN = {
    Text = "Be more devout, offer more sacrifices... the Divine Realm watches your prayers and will answer you one day."
  },
  LanguageConfig_LotteryPhoneticDialogue11_CN = {
    Text = "Even the most ordinary soul can be moved by these verses... This flower blooms for you!"
  },
  LanguageConfig_LotteryPhoneticDialogue12_CN = {
    Text = "Poems carry their own emotions, just as flowers carry their own meanings. This one is for you."
  },
  LanguageConfig_LotteryPhoneticDialogue13_CN = {
    Text = "Behold, I shall fight on forever."
  },
  LanguageConfig_LotteryPhoneticDialogue14_CN = {
    Text = "Have you come to witness my triumph?"
  },
  LanguageConfig_LotteryPhoneticDialogue15_CN = {
    Text = "Struggle all you like, my dear. Would you like the teacher to give you a pat on the head?"
  },
  LanguageConfig_LotteryPhoneticDialogue16_CN = {
    Text = "With nothing but junk like this, what do you think you can save?"
  },
  LanguageConfig_LotteryPhoneticDialogue17_CN = {
    Text = "Oh, you got quite lucky, dear customer. Would you like to try again?"
  },
  LanguageConfig_LotteryPhoneticDialogue18_CN = {
    Text = "Would you like to take another look? My shop has even more precious items in stock."
  },
  LanguageConfig_LotteryPhoneticDialogue19_CN = {
    Text = "This report is quite delectable. My thanks for the treat."
  },
  LanguageConfig_LotteryPhoneticDialogue1_CN = {
    Text = "Thank you for your kindness, dear."
  },
  LanguageConfig_LotteryPhoneticDialogue20_CN = {
    Text = "Mm, I'll take it. Anything else?"
  },
  LanguageConfig_LotteryPhoneticDialogue21_CN = {
    Text = "Thank you for your gift. Please accept these in return."
  },
  LanguageConfig_LotteryPhoneticDialogue22_CN = {
    Text = "I've found some rare materials. I hope they'll be of use to you."
  },
  LanguageConfig_LotteryPhoneticDialogue23_CN = {
    Text = "A simple appetizer, bon appétit."
  },
  LanguageConfig_LotteryPhoneticDialogue24_CN = {
    Text = "This dish was prepared by His Majesty's own hand. We hope it pleases your palate."
  },
  LanguageConfig_LotteryPhoneticDialogue25_CN = {
    Text = "Don't be too caught up in techniques and rules."
  },
  LanguageConfig_LotteryPhoneticDialogue26_CN = {
    Text = "Rationality only teaches you to mimic, while madness allows you to create."
  },
  LanguageConfig_LotteryPhoneticDialogue27_CN = {
    Text = "People fear madness because they have never glimpsed the truth."
  },
  LanguageConfig_LotteryPhoneticDialogue28_CN = {
    Text = "Did you see it? The real world!"
  },
  LanguageConfig_LotteryPhoneticDialogue29_CN = {
    Text = "I saw the true colors. How magnificent."
  },
  LanguageConfig_LotteryPhoneticDialogue2_CN = {
    Text = "My, what wonderful luck! Take good care of it."
  },
  LanguageConfig_LotteryPhoneticDialogue30_CN = {
    Text = "Madness and absurdity are the beauty of reality and the beauty of art!"
  },
  LanguageConfig_LotteryPhoneticDialogue31_CN = {
    Text = "Darkness. The stain remains. Keep going, you must wash away your sins."
  },
  LanguageConfig_LotteryPhoneticDialogue32_CN = {
    Text = "How beautiful, I see your pure soul..."
  },
  LanguageConfig_LotteryPhoneticDialogue33_CN = {
    Text = [[
Hey, Keeper! Even if things played out exactly the same, you'd still save me, right?
...Then I can sleep easily. Th-ahem, I mean, thank you.]]
  },
  LanguageConfig_LotteryPhoneticDialogue34_CN = {
    Text = "I've been dreaming about the past constantly lately. It's driving me mad. This better be useful."
  },
  LanguageConfig_LotteryPhoneticDialogue35_CN = {
    Text = "The Divine Mother has made a noble sacrifice for Lemuria, and we are willing to exchange everything for her peace."
  },
  LanguageConfig_LotteryPhoneticDialogue36_CN = {
    Text = "Thank you for your tribute to the Divine Mother; I hope this brings her a good night's sleep."
  },
  LanguageConfig_LotteryPhoneticDialogue37_CN = {
    Text = "This dream will cycle on without end, and you...\nBe grateful—I shall permit you to be part of it."
  },
  LanguageConfig_LotteryPhoneticDialogue38_CN = {
    Text = "Have you ever seen what my dreams look like? That kind of filth, utterly corrupt to the core..."
  },
  LanguageConfig_LotteryPhoneticDialogue39_CN = {
    Text = "How redundant worldly possessions are. If you have any wish, why not whisper it straight to me...?"
  },
  LanguageConfig_LotteryPhoneticDialogue3_CN = {
    Text = "You've truly struck gold, young one! Everything in my shop is an ancient relic!"
  },
  LanguageConfig_LotteryPhoneticDialogue40_CN = {
    Text = "If you find yourself amid the desolate ruins of the Far East, beware—do not offer worship recklessly. Ghosts or demons? Heh... those are hardly worth mentioning."
  },
  LanguageConfig_LotteryPhoneticDialogue41_CN = {
    Text = "Coalsie, the best!"
  },
  LanguageConfig_LotteryPhoneticDialogue42_CN = {
    Text = "Coalsie, awesome!"
  },
  LanguageConfig_LotteryPhoneticDialogue43_CN = {
    Text = "Shiny! For you, Coalsie!"
  },
  LanguageConfig_LotteryPhoneticDialogue44_CN = {
    Text = "Friend, like it! Vortice, Coalsie, exchange!"
  },
  LanguageConfig_LotteryPhoneticDialogue45_CN = {
    Text = "Conch, so beautiful! Vortice, collect! Coalsie, prizes!"
  },
  LanguageConfig_LotteryPhoneticDialogue46_CN = {
    Text = "Vortice, likes it! Thank you, Coalsie!"
  },
  LanguageConfig_LotteryPhoneticDialogue47_CN = {
    Text = "That's right... You who have been forsaken by fate, now shatter its cage!"
  },
  LanguageConfig_LotteryPhoneticDialogue48_CN = {
    Text = "Ah, a cruel little jest of Fate."
  },
  LanguageConfig_LotteryPhoneticDialogue49_CN = {
    Text = "Breeding, growing up—without love, none of these things could happen for me."
  },
  LanguageConfig_LotteryPhoneticDialogue4_CN = {
    Text = "Chosen by such powerful magic... Could you be the legendary Chosen One?"
  },
  LanguageConfig_LotteryPhoneticDialogue50_CN = {
    Text = "When I arrived in that world alone, still very young, I learned so much from a certain person. I've kept pushing myself to learn every day since."
  },
  LanguageConfig_LotteryPhoneticDialogue51_CN = {
    Text = [[
Have you ever been loved by someone without reservation, or loved someone with everything you had? 
I think... it's a very beautiful thing.]]
  },
  LanguageConfig_LotteryPhoneticDialogue52_CN = {
    Text = [[
Human love, no, the love of living beings, is truly wonderful..
You'll have someone more important than yourself, more important than anything else.]]
  },
  LanguageConfig_LotteryPhoneticDialogue53_CN = {
    Text = "Please wait with me for the start of that radiant, glorious, and beautiful world."
  },
  LanguageConfig_LotteryPhoneticDialogue54_CN = {
    Text = "Thank you for the gift. It will surely bring us new discoveries."
  },
  LanguageConfig_LotteryPhoneticDialogue55_CN = {
    Text = "What? Seriously? You just hit the jackpot?!"
  },
  LanguageConfig_LotteryPhoneticDialogue56_CN = {
    Text = "You'd believe a word out of some little girl?"
  },
  LanguageConfig_LotteryPhoneticDialogue57_CN = {
    Text = "Wonderful! No, what I'm looking for isn't here... but I'm so happy for what everyone else has won."
  },
  LanguageConfig_LotteryPhoneticDialogue58_CN = {
    Text = "I... I am sure your wishes will all come true. I have faith in that."
  },
  LanguageConfig_LotteryPhoneticDialogue59_CN = {
    Text = "Hehe, Come on, don't run away now~ Savor it properly, this is the real thing—the fairy's own blessing!"
  },
  LanguageConfig_LotteryPhoneticDialogue5_CN = {
    Text = "Huh? Oh, take it. Thanks for your kindness, or whatever."
  },
  LanguageConfig_LotteryPhoneticDialogue60_CN = {
    Text = "So close, just the teensiest bit more! One more try, hmm?"
  },
  LanguageConfig_LotteryPhoneticDialogue61_CN = {
    Text = "Suggested Translation"
  },
