  LanguageConfig_LotteryPhoneticDialogue6_CN = {
    Text = "Oh, not bad luck at all. Unlike Big John next door, my wares are all about practical results. Hope it serves you well."
  },
  LanguageConfig_LotteryPhoneticDialogue7_CN = {
    Text = "Reveal your deepest desires to me... I will grant you what you crave."
