  LanguageConfig_RailWayStageDifficultyBuffContent1_CN = {
    Text = "<Title:Phase Rewards>\nFirst Phase: Defeat Elite/Boss to earn \"VIP Points\" ×25/75 \nSecond Phasre: Defeat Elite/Boss to earn \"VIP Points\" ×50/150 \nThird Phase: Defeat Elite/Boss to earn \"VIP Points\" ×75/225\n<Title:Starting Relics>\nGain \"Little N's Pristine Camera\" at start.\n<OrangeQuality:Golden Harmony>: \"Arithmetica Harmony\" now only increases Arithmetica Cost by 1. Each 1% DMG Amplification increases Occult Research Depth by 1%.\n<RedQuality:Transit Fatigue>: Healing effects -50% in battle."
  },
  LanguageConfig_RailWayStageDifficultyBuffContent2_CN = {
    Text = [[
<Title:Special Rules>
The higher the difficulty, the more VIP Points you will earn. If you finished all three Phases, VIP Points +150%.
<Title:Starting Relics>
Gain "Little N's Worn Camera" at start.
<OrangeQuality:Golden Harmony>: "Arithmetica Harmony" now only increases Arithmetica Cost by 1. Each 1% DMG Amplification increases Occult Research Depth by 1%.
<OrangeQuality:Dimensional Gift>: Gain 1 random Dimensional Relic at start. Hand Limit +1.
<RedQuality:Transit Fatigue>: Healing -50% in battle.
<RedQuality:Motion Vertigo>: Start battle with -50% Aliemus/Keyflare.]]
  },
  LanguageConfig_RailWayStageDifficultyBuffContent3V2_CN = {
    Text = "<Title:Special Challenge>\nUnder Madness Difficulty, after completing Phase 3, an additional Phase 4 final Boss \"Tawil\" challenge will be unlocked.\n<Title:Stage Rewards>\nThe higher the challenge difficulty, the more \"VIP Points\" you will earn. \"VIP Points\" earned from completing three phases increased by 400%.\nAfter defeating the final Boss \"Tawil\", you can additionally earn \"VIP Points\" × 1500.\n<Title:Initial Relics>\nAt the start of the Investigation, obtain the Relic \"Little \"N\"'s Chaotic Camera\"\n·<OrangeQuality:Golden Harmony>: The maximum Arithmetica increase effect from \"Arithmetica Harmony\" is 1 point. For every 1% DMG Amplification owned, the Occult Research effect increases by 1%.\n·<OrangeQuality:Dimensional Gift>: At the start of exploration, randomly obtain 1 Dimensional Image Relic, and the Maximum Hand Size increases by 2.\n·<OrangeQuality:Blessed Ritual>: The Boss rewards for Phase 1 and Phase 2 are changed to a choice of 1 from 3 random Blessed Relics.\n·<RedQuality:Transit Fatigue>: All HP Healing effects in battle are reduced by 50%.\n·<RedQuality:Motion Vertigo>: At the start of battle, all Awakeners' current Aliemus and Keyflare are reduced by 50%.\n·<RedQuality:Evernight Rail>: At the start of exploration, all Awakeners' Base Aliemus and maximum Keyflare are increased by 50%."
  },
  LanguageConfig_RailWayStageDifficultyBuffContent3_CN = {
    Text = "<Title:Stage Rewards>\nThe higher the challenge difficulty, the more \"VIP Points\" you will earn. Completing all three stages increases \"VIP Points\" gained by 400%\n<Title:Starting Relic>\nAt the start of the investigation, obtain the Relic \"Little N's Chaotic Camera\"\n·<OrangeQuality:Golden Harmony>: The Arithmetica boost effect from \"Arithmetica Harmony\" is capped at 1, and every 1% of DMG Amplification increases the Occult Research effect by 1%.\n·<OrangeQuality:Dimensional Gift>: At the start of exploration, randomly obtain 1 Dimensional Image Relic, and Hand Limit increases by 2.\n·<OrangeQuality:Blessed Ritual>: The rewards for defeating the Stage 1 and Stage 2 Bosses are changed to a choice of 1 from 3 random Blessed Relics.\n·<RedQuality:Transit Fatigue>: All HP Healing effects are reduced by 50% during combat.\n·<RedQuality:Motion Vertigo>: At the start of combat, all Awakeners' current Aliemus and Keyflare are reduced by 50%.\n·<RedQuality:Evernight Rail>: At the start of exploration, all Awakeners' Base Aliemus and Keyflare cap are increased by 50%"
