  LanguageConfig_SchoolTowerRuleTxt_CN = {
    Text = [[
<Title:Lightless Realm>
The Lightless Realm consists of high-difficulty stages. Clearing these stages grants rich rewards. Additionally, accumulating star ratings provides extra rewards.

