  LanguageConfig_StorylineGuide_0_CN = {
    Text = "We live to die."
  },
  LanguageConfig_StorylineGuide_10_CN = {
    Text = [[
Entropy is the ultimate conclusion. 
Nevertheless, there are those who refuse to abandon their defiance.]]
  },
  LanguageConfig_StorylineGuide_11_CN = {
    Text = [[
Dare not look upon the cosmos above. 
Dare not look upon the abyss within.]]
  },
  LanguageConfig_StorylineGuide_12_CN = {
    Text = "To dine is the first art we ever learn."
  },
  LanguageConfig_StorylineGuide_13_CN = {
    Text = "There are no answers in this boundless dream. It is time to wake up."
  },
  LanguageConfig_StorylineGuide_14_CN = {
    Text = "Upon the stage of fate, we never get to choose the roles we play."
  },
  LanguageConfig_StorylineGuide_15_CN = {
    Text = "O Travelers, pray walk gently into that snowy night. On the summit of voided wills, may you witness the end of a grand dream."
  },
  LanguageConfig_StorylineGuide_16_CN = {
    Text = "Suggested Translation"
  },
  LanguageConfig_StorylineGuide_17_CN = {
    Text = "Suggested Translation"
  },
