  LanguageConfig_TrinketBindRuleDesc_CN = {
    Text = "<Title:Covenant Binding>\nKeepers can now bind Covenants to Awakeners.\nEach Awakener has 6 binding slots (one Covenant per slot).\nOnce bound, the Covenant’s primary attribute is increased by 50%.\nBound Covenants will not appear in your Inventory or the Alchemy system.\nIf an Awakener has no Covenant equipped in a lineup or Support slot, their bound Covenant will be automatically equipped.\nUpgrading a bound Covenant will not unbind it; its boosted attributes will update automatically.\n\n<Title:Covenant Unbind>\nTo change or remove a bind, use the unbind option on the Covenant Bind screen.\nUnbinding a single slot costs 10 Covenants of the same type (any slot position can be used as cost)."
